# Lei 8.112/90 — lote L2, parte b (remuneração, vantagens, licenças, afastamentos, petição, deveres, acumulação, penalidades)
JUR = lambda ref: {"fonte": {"tipo": "sumula", "ref": ref, "conferida": "conhecimento"}, "risco": ["jurisprudencia_mutavel"]}
Q = [
# P11 complemento
("P11",["38"],"E","troca_efeito",2,"O substituto de ocupante de cargo de direção ou chefia assume o cargo somente se for expressamente designado a cada afastamento do titular, e deve acumular as remunerações dos dois cargos durante o período.","Art. 38, § 1º: o substituto assume automática e cumulativamente, mas deve optar pela remuneração de um deles.","acumula remunerações","p11d",{}),
("P11",["36"],"C","caso_concreto",3,"A remoção, a pedido, para acompanhar cônjuge ou companheiro servidor público civil ou militar, de qualquer dos Poderes da União, dos Estados, do DF e dos Municípios, que foi deslocado no interesse da Administração, ocorre independentemente do interesse da Administração.","Art. 36, parágrafo único, III, a.","","p11f",{"fonte":{"tipo":"lei","ref":"Lei 8.112/1990, art. 36, parágrafo único, III","conferida":"conhecimento"}}),
("P11",["36"],"E","caso_concreto",3,"A remoção de ofício, no interesse da Administração, e a remoção a pedido, a critério da Administração, são as únicas modalidades de remoção previstas na lei, ainda que o servidor deseje acompanhar cônjuge ou companheiro deslocado no interesse da Administração.","Art. 36, parágrafo único: há também a remoção a pedido, para outra localidade, independentemente do interesse da Administração (III).","omite modalidade","p11f",{"fonte":{"tipo":"lei","ref":"Lei 8.112/1990, art. 36, parágrafo único","conferida":"conhecimento"}}),
# P12
("P12",["40","41"],"C","conceito_correto",1,"Vencimento é a retribuição pecuniária pelo exercício de cargo público, com valor fixado em lei, e remuneração é o vencimento do cargo efetivo acrescido das vantagens pecuniárias permanentes estabelecidas em lei.","Arts. 40 e 41.","","p12a",{}),
("P12",["40","41"],"E","confusao_instituto",1,"Vencimento é o vencimento do cargo efetivo acrescido das vantagens pecuniárias permanentes, e remuneração é a retribuição pecuniária fixada em lei pelo exercício do cargo.","Conceitos trocados: vencimento (art. 40) é o valor-base; remuneração (art. 41) soma vantagens permanentes.","troca vencimento por remuneração","p12a",{}),
("P12",["41"],"C","conceito_correto",2,"O vencimento do cargo efetivo, acrescido das vantagens de caráter permanente, é irredutível, e nenhum servidor receberá remuneração inferior ao salário mínimo.","Art. 41, §§ 3º e 5º.","","p12b",{}),
("P12",["41"],"E","restricao_indevida",2,"A irredutibilidade protege somente o vencimento básico, podendo ser reduzidas as vantagens de caráter permanente, e a remuneração do servidor pode ser inferior ao salário mínimo.","Art. 41, §§ 3º e 5º: irredutibilidade abrange vencimento e vantagens permanentes; remuneração não pode ser inferior ao salário mínimo.","restringe irredutibilidade","p12b",{}),
("P12",["41"],"C","conceito_correto",3,"É assegurada a isonomia de vencimentos para cargos de atribuições iguais ou assemelhadas do mesmo Poder, ou entre servidores dos três Poderes, ressalvadas as vantagens de caráter individual e as relativas à natureza ou ao local de trabalho.","Art. 41, § 4º.","","p12c",{}),
("P12",["42"],"C","conceito_correto",3,"Nenhum servidor poderá perceber, mensalmente, remuneração superior à soma dos valores percebidos como remuneração, em espécie, no âmbito dos respectivos Poderes, pelos Ministros de Estado, membros do Congresso Nacional e Ministros do STF, excluídas do teto as vantagens dos incisos II a VII do art. 61.","Art. 42, caput e parágrafo único.","","p12d",{}),
("P12",["42"],"E","troca_efeito",3,"O teto de remuneração fixado em lei abrange todas as vantagens percebidas pelo servidor, inclusive a gratificação natalina, o adicional de férias e os adicionais de insalubridade e de serviço extraordinário, sem exclusões.","Art. 42, parágrafo único: excluem-se do teto as vantagens dos incisos II a VII do art. 61 (natalina, insalubridade, extraordinário, noturno, férias).","inclui vantagens excluídas","p12d",{}),
("P12",["44"],"C","caso_concreto",2,"Servidor que faltar ao serviço sem motivo justificado perderá a remuneração do dia em que faltar.","Art. 44, I.","","p12e",{}),
("P12",["44"],"E","caso_concreto",2,"Servidor que faltar ao serviço sem motivo justificado perderá a remuneração de toda a semana em que faltar.","Art. 44, I: perde a remuneração do dia em que faltar.","amplia perda","p12e",{}),
("P12",["45"],"C","troca_numero",2,"Mediante autorização do servidor, pode haver consignação em folha em favor de terceiros, a critério da administração; o total das consignações facultativas não excederá 35% da remuneração mensal, sendo 5% reservados exclusivamente para outras finalidades previstas na lei.","Art. 45, §§ 1º e 2º.","","p12f",{}),
("P12",["45"],"E","troca_numero",2,"Salvo por imposição legal ou mandado judicial, nenhum desconto incidirá sobre a remuneração; o total das consignações facultativas em favor de terceiros, autorizadas pelo servidor, poderá chegar a 50% da remuneração mensal.","Art. 45: nenhum desconto salvo imposição legal ou mandado judicial; consignações facultativas não excedem 35%.","eleva limite de consignação","p12f",{}),
("P12",["46","47"],"C","troca_numero",2,"O servidor em débito com o erário que for demitido ou exonerado terá o prazo de sessenta dias para quitar o débito, e a não quitação implicará inscrição em dívida ativa.","Art. 47, caput e parágrafo único.","","p12g",{}),
("P12",["47"],"E","troca_numero",2,"O servidor em débito com o erário que for demitido ou exonerado terá o prazo de trinta dias para quitar o débito, e a não quitação implicará desconto automático nas verbas rescisórias.","Art. 47: sessenta dias; a não quitação implica inscrição em dívida ativa.","altera prazo e consequência","p12g",{}),
("P12",["48"],"C","excecao_omitida",2,"O vencimento, a remuneração e o provento não serão objeto de arresto, sequestro ou penhora, exceto nos casos de prestação de alimentos resultante de decisão judicial.","Art. 48.","","p12h",{}),
("P12",["48"],"E","excecao_omitida",2,"O vencimento, a remuneração e o provento são impenhoráveis em qualquer hipótese, inclusive no caso de prestação de alimentos decorrente de decisão judicial.","Art. 48: a exceção é a prestação de alimentos resultante de decisão judicial.","nega a exceção","p12h",{}),
# P13
("P13",["49","51"],"C","conceito_correto",2,"Além do vencimento, poderão ser pagas ao servidor indenizações, gratificações e adicionais, constituindo indenizações a ajuda de custo, as diárias, o transporte e o auxílio-moradia.","Arts. 49 e 51.","","p13a",{}),
("P13",["49"],"E","troca_efeito",2,"As indenizações incorporam-se ao vencimento ou provento para todos os efeitos, ao passo que as gratificações e os adicionais jamais se incorporam, constituindo indenizações a ajuda de custo e as diárias.","Art. 49, §§ 1º e 2º: indenizações não se incorporam para qualquer efeito; gratificações e adicionais incorporam-se nos casos e condições da lei.","inverte incorporação","p13a",{}),
("P13",["54"],"C","troca_numero",2,"A ajuda de custo é calculada sobre a remuneração do servidor, conforme regulamento, não podendo exceder a importância correspondente a três meses.","Art. 54.","","p13b",{}),
("P13",["54"],"E","troca_numero",2,"A ajuda de custo é calculada sobre o vencimento, conforme regulamento, não podendo exceder a importância correspondente a seis meses.","Art. 54: calculada sobre a remuneração, limite de três meses.","altera limite e base","p13b",{}),
("P13",["53"],"C","excecao_omitida",3,"Não será concedida ajuda de custo nas hipóteses de remoção a pedido a critério da Administração e a pedido, independentemente do interesse da Administração (art. 36, parágrafo único, II e III).","Art. 53, § 3º.","","p13c",{}),
("P13",["53"],"E","excecao_omitida",3,"A ajuda de custo é devida em qualquer modalidade de remoção, inclusive a pedido, a critério da Administração ou independentemente do interesse da Administração (art. 36, parágrafo único, II e III).","Art. 53, § 3º: não se concede ajuda de custo nas remoções dos incisos II e III do art. 36, parágrafo único.","ignora a exceção","p13c",{}),
("P13",["53","57"],"C","troca_numero",3,"O servidor ficará obrigado a restituir a ajuda de custo quando, injustificadamente, não se apresentar na nova sede no prazo de trinta dias.","Art. 57.","","p13d",{}),
("P13",["55"],"C","excecao_omitida",2,"Não será concedida ajuda de custo ao servidor que se afastar do cargo, ou reassumi-lo, em virtude de mandato eletivo.","Art. 55.","","p13e",{}),
("P13",["58"],"C","caso_concreto",3,"Servidor que se deslocar a serviço, em caráter eventual, para outro ponto do território nacional faz jus a diárias, devidas pela metade quando o deslocamento não exigir pernoite fora da sede.","Art. 58, caput e § 1º.","","p13f",{}),
("P13",["58"],"E","caso_concreto",3,"Servidor cujo deslocamento da sede constitua exigência permanente do cargo faz jus a diárias, devidas integralmente mesmo quando o deslocamento não exigir pernoite fora da sede.","Art. 58, § 2º: nesse caso não há direito a diárias; § 1º: metade, sem pernoite.","ignora vedação","p13f",{}),
("P13",["59"],"C","troca_numero",3,"O servidor que receber diárias e não se afastar da sede, por qualquer motivo, fica obrigado a restituí-las integralmente no prazo de cinco dias.","Art. 59, caput.","","p13g",{}),
("P13",["59"],"E","troca_numero",3,"O servidor que receber diárias e não se afastar da sede, por qualquer motivo, deve restituí-las apenas em metade, no prazo de trinta dias.","Art. 59: restituição integral, em cinco dias.","altera valor e prazo","p13g",{}),
("P13",["60","60A"],"C","conceito_correto",3,"O auxílio-moradia consiste no ressarcimento das despesas comprovadamente realizadas pelo servidor com aluguel de moradia ou com meio de hospedagem administrado por empresa hoteleira.","Art. 60-A.","","p13h",{}),
("P13",["60D"],"E","troca_numero",3,"O valor mensal do auxílio-moradia é limitado a 50% do valor do cargo em comissão, função comissionada ou cargo de Ministro de Estado ocupado, sendo garantido aos que preencherem os requisitos o ressarcimento até R$ 1.800,00.","Art. 60-D: limite de 25%.","altera percentual","p13h",{}),
# P14
("P14",["63","64"],"C","troca_numero",2,"A gratificação natalina corresponde a 1/12 da remuneração a que o servidor fizer jus em dezembro, por mês de exercício no respectivo ano, e a fração igual ou superior a quinze dias é considerada mês integral.","Art. 63, caput e parágrafo único.","","p14a",{}),
("P14",["63"],"E","troca_numero",2,"A gratificação natalina corresponde a 1/12 da remuneração a que o servidor fizer jus em dezembro, por mês de exercício no respectivo ano, e a fração igual ou superior a dez dias é considerada mês integral.","Art. 63, parágrafo único: fração igual ou superior a quinze dias.","altera fração","p14a",{}),
("P14",["64","65"],"C","conceito_correto",2,"A gratificação natalina será paga até o dia vinte do mês de dezembro, e o servidor exonerado a perceberá proporcionalmente aos meses de exercício, calculada sobre a remuneração do mês da exoneração.","Arts. 64 e 65.","","p14b",{}),
("P14",["68"],"C","conceito_correto",2,"O servidor que fizer jus aos adicionais de insalubridade e de periculosidade deverá optar por um deles, e o direito cessa com a eliminação das condições ou dos riscos que lhe deram causa.","Art. 68, §§ 1º e 2º.","","p14c",{}),
("P14",["68"],"E","troca_efeito",2,"O servidor que trabalhe em local insalubre e perigoso tem direito a receber cumulativamente os adicionais de insalubridade e de periculosidade, mantidos ainda que cessem os riscos.","Art. 68, §§ 1º e 2º: deve optar por um deles; o direito cessa com a eliminação das condições.","permite cumulação","p14c",{}),
("P14",["69"],"C","conceito_correto",2,"A servidora gestante ou lactante será afastada, enquanto durar a gestação e a lactação, das operações e locais penosos, insalubres ou perigosos, exercendo suas atividades em local salubre e em serviço não penoso e não perigoso.","Art. 69, parágrafo único.","","p14d",{}),
("P14",["73","74"],"C","troca_numero",2,"O serviço extraordinário será remunerado com acréscimo de cinquenta por cento em relação à hora normal e somente é permitido para atender a situações excepcionais e temporárias, respeitado o limite máximo de duas horas por jornada.","Arts. 73 e 74.","","p14e",{}),
("P14",["73","74"],"E","troca_numero",2,"O serviço extraordinário será remunerado com acréscimo de vinte e cinco por cento em relação à hora normal e poderá ser prestado com habitualidade, respeitado o limite máximo de quatro horas por jornada.","Arts. 73 e 74: 50%; somente em situações excepcionais e temporárias, limite de 2 horas por jornada.","altera percentual e limite","p14e",{}),
("P14",["75"],"C","troca_numero",3,"O serviço noturno, prestado entre 22 horas de um dia e 5 horas do dia seguinte, terá o valor-hora acrescido de 25%, computando-se cada hora como 52 minutos e 30 segundos.","Art. 75, caput.","","p14f",{}),
("P14",["75"],"E","troca_numero",3,"O serviço noturno, prestado entre 21 horas de um dia e 6 horas do dia seguinte, terá o valor-hora acrescido de 50%, computando-se cada hora como 60 minutos.","Art. 75: 22h às 5h; acréscimo de 25%; hora de 52 minutos e 30 segundos.","altera horário, percentual e hora","p14f",{}),
("P14",["76"],"C","conceito_correto",2,"O adicional de férias, correspondente a 1/3 da remuneração do período, será pago independentemente de solicitação do servidor, por ocasião das férias.","Art. 76, caput.","","p14g",{}),
("P14",["76A"],"C","troca_numero",3,"A Gratificação por Encargo de Curso ou Concurso não se incorpora ao vencimento para qualquer efeito, não pode ser base de cálculo de outras vantagens e a retribuição não poderá exceder, em regra, o equivalente a 120 horas de trabalho anuais.","Art. 76-A, § 1º, II, e § 3º.","","p14h",{}),
("P14",["76A"],"E","troca_efeito",3,"A Gratificação por Encargo de Curso ou Concurso incorpora-se ao vencimento e compõe os proventos de aposentadoria e pensões quando paga por mais de cinco anos, podendo servir de base de cálculo de outras vantagens.","Art. 76-A, § 3º: não se incorpora para qualquer efeito, nem compõe proventos e pensões.","admite incorporação","p14h",{}),
# P15
("P15",["77"],"C","conceito_correto",2,"O servidor fará jus a trinta dias de férias, que podem ser acumuladas, até o máximo de dois períodos, no caso de necessidade do serviço, e o primeiro período aquisitivo exige doze meses de exercício.","Art. 77, caput e § 1º.","","p15a",{}),
("P15",["77"],"E","troca_numero",2,"O servidor fará jus a trinta dias de férias, que podem ser acumuladas, até o máximo de três períodos, e o primeiro período aquisitivo exige seis meses de exercício.","Art. 77: máximo de dois períodos; doze meses de exercício.","altera números","p15a",{}),
("P15",["77"],"C","conceito_correto",3,"As férias poderão ser parceladas em até três etapas, desde que assim requeridas pelo servidor e no interesse da administração pública, sendo vedado levar à conta de férias qualquer falta ao serviço.","Art. 77, §§ 2º e 3º.","","p15b",{}),
("P15",["77"],"E","troca_autoridade",3,"As férias poderão ser parceladas em até quatro etapas, por determinação da chefia e no interesse da administração pública, ainda que contra a vontade do servidor, podendo faltas ao serviço ser levadas à conta de férias.","Art. 77, § 3º: até três etapas, desde que requeridas pelo servidor e no interesse da administração.","altera número e iniciativa","p15b",{}),
("P15",["78"],"C","conceito_correto",2,"O pagamento da remuneração das férias será efetuado até dois dias antes do início do respectivo período.","Art. 78, caput.","","p15c",{}),
("P15",["80"],"C","excecao_omitida",3,"As férias somente poderão ser interrompidas por motivo de calamidade pública, comoção interna, convocação para júri, serviço militar ou eleitoral, ou por necessidade do serviço declarada pela autoridade máxima do órgão ou entidade; o restante será gozado de uma só vez.","Art. 80.","","p15d",{}),
("P15",["80"],"E","restricao_indevida",3,"As férias podem ser interrompidas por simples determinação do chefe imediato, quando houver conveniência do serviço, ou por calamidade pública ou convocação para júri, devendo o restante do período ser gozado em duas etapas.","Art. 80: hipóteses taxativas; necessidade do serviço deve ser declarada pela autoridade máxima; restante gozado de uma só vez.","amplia interrupção","p15d",{}),
# P16 Licenças
("P16",["81"],"C","conceito_correto",2,"Conceder-se-á ao servidor licença por motivo de doença em pessoa da família, por motivo de afastamento do cônjuge ou companheiro, para o serviço militar, para atividade política, para capacitação, para tratar de interesses particulares e para desempenho de mandato classista.","Art. 81, I a VII.","","p16a",{}),
("P16",["81"],"E","confusao_instituto",2,"Entre as licenças previstas no art. 81 estão a licença à gestante, a licença-paternidade, a licença para tratamento da própria saúde e a licença por acidente em serviço.","Art. 81 não lista essas licenças (previstas nos arts. 202 e seguintes e no art. 207/208).","inclui licenças de outro rol","p16a",{}),
("P16",["82"],"C","troca_numero",3,"A licença concedida dentro de sessenta dias do término de outra da mesma espécie será considerada prorrogação.","Art. 82.","","p16b",{}),
("P16",["82"],"E","troca_numero",3,"A licença concedida dentro de trinta dias do término de outra da mesma espécie será considerada prorrogação.","Art. 82: sessenta dias.","altera prazo","p16b",{}),
("P16",["83"],"C","troca_numero",3,"A licença por motivo de doença em pessoa da família pode ser concedida, a cada período de doze meses, por até sessenta dias, consecutivos ou não, mantida a remuneração, e por até noventa dias, consecutivos ou não, sem remuneração.","Art. 83, § 2º, I e II.","","p16c",{}),
("P16",["83"],"E","troca_numero",3,"A licença por motivo de doença em pessoa da família pode ser concedida, a cada período de doze meses, por até noventa dias, consecutivos ou não, mantida a remuneração, e por até sessenta dias, consecutivos ou não, sem remuneração.","Art. 83, § 2º: 60 dias com remuneração e 90 dias sem remuneração.","inverte prazos","p16c",{}),
("P16",["83"],"C","caso_concreto",3,"Servidor que pleiteia licença para cuidar de filho doente terá o pedido deferido somente se comprovada, por perícia médica oficial, a doença e se a assistência direta for indispensável e não puder ser prestada simultaneamente com o exercício do cargo ou mediante compensação de horário.","Art. 83, caput e § 1º.","","p16d",{}),
("P16",["83"],"E","caso_concreto",3,"Servidor que pleiteia licença para cuidar de filho doente terá direito à licença mediante simples atestado de médico particular, ainda que a assistência direta pudesse ser prestada simultaneamente com o exercício do cargo ou mediante compensação de horário.","Art. 83: exige perícia médica oficial e indispensabilidade da assistência direta, que não possa ser prestada com compensação.","dispensa perícia oficial","p16d",{}),
("P16",["81"],"E","restricao_indevida",2,"É vedado o exercício de atividade remunerada durante o período da licença por motivo de doença em pessoa da família, salvo se compatível com o horário do cargo.","Art. 81, § 3º: vedação sem a ressalva de compatibilidade.","cria ressalva inexistente","p16e",{}),
("P16",["81"],"C","conceito_correto",2,"É vedado o exercício de atividade remunerada durante o período da licença por motivo de doença em pessoa da família.","Art. 81, § 3º.","","p16e",{}),
("P16",["84"],"C","conceito_correto",2,"A licença para acompanhar cônjuge ou companheiro deslocado para outro ponto do território nacional, para o exterior ou para o exercício de mandato eletivo dos Poderes Executivo e Legislativo será por prazo indeterminado e sem remuneração.","Art. 84, caput e § 1º.","","p16f",{}),
("P16",["84"],"E","troca_efeito",2,"A licença para acompanhar cônjuge ou companheiro deslocado para outro ponto do território nacional, para o exterior ou para o exercício de mandato eletivo será por prazo de até três anos e com remuneração integral.","Art. 84, § 1º: prazo indeterminado e sem remuneração.","altera prazo e remuneração","p16f",{}),
("P16",["86"],"C","caso_concreto",3,"O servidor que for escolhido em convenção partidária como candidato a cargo eletivo terá direito a licença, sem remuneração, durante o período entre a escolha e a véspera do registro de sua candidatura perante a Justiça Eleitoral.","Art. 86, caput.","","p16g",{}),
("P16",["86"],"C","caso_concreto",3,"O servidor candidato na localidade onde desempenha suas funções e que exerça cargo de direção, chefia, assessoramento, arrecadação ou fiscalização será afastado do cargo a partir do dia seguinte ao do registro da candidatura até o décimo dia seguinte ao do pleito.","Art. 86, § 1º.","","p16h",{}),
("P16",["86"],"E","troca_efeito",3,"O servidor candidato na localidade onde desempenha suas funções e que exerça cargo de direção, chefia, assessoramento, arrecadação ou fiscalização será afastado do cargo a partir do registro da candidatura até o trigésimo dia seguinte ao do pleito.","Art. 86, § 1º: afastamento a partir do dia imediato ao do registro da candidatura até o décimo dia seguinte ao do pleito.","altera período","p16h",{}),
("P16",["87"],"C","troca_numero",2,"Após cada quinquênio de efetivo exercício, o servidor poderá, no interesse da Administração, afastar-se do cargo efetivo, com remuneração, por até três meses, para participar de curso de capacitação profissional, sendo os períodos não acumuláveis.","Art. 87, caput e parágrafo único.","","p16i",{}),
("P16",["87"],"E","troca_numero",2,"Após cada triênio de efetivo exercício, o servidor poderá, no interesse da Administração, afastar-se do cargo efetivo, sem remuneração, por até seis meses, para curso de capacitação profissional, podendo acumular os períodos.","Art. 87: quinquênio; com remuneração; até três meses; períodos não acumuláveis.","altera várias condições","p16i",{}),
("P16",["91"],"C","caso_concreto",3,"A critério da Administração, poderá ser concedida licença para trato de assuntos particulares, pelo prazo de até três anos consecutivos e sem remuneração, ao servidor ocupante de cargo efetivo que não esteja em estágio probatório.","Art. 91, caput.","","p16j",{}),
("P16",["91"],"E","caso_concreto",3,"Servidor em estágio probatório que preencha os requisitos poderá exigir a licença para trato de assuntos particulares, que será concedida pelo prazo de até três anos consecutivos e com remuneração.","Art. 91: a critério da Administração, não em estágio probatório, sem remuneração.","tira o caráter discricionário","p16j",{}),
("P16",["91"],"C","conceito_correto",2,"A licença para trato de assuntos particulares poderá ser interrompida, a qualquer tempo, a pedido do servidor ou no interesse do serviço.","Art. 91, parágrafo único.","","p16k",{}),
("P16",["92"],"C","conceito_correto",3,"É assegurado ao servidor o direito à licença sem remuneração para o desempenho de mandato em confederação, federação, associação de classe de âmbito nacional ou sindicato representativo da categoria, somente podendo ser licenciados os eleitos para cargos de direção ou representação nas entidades cadastradas.","Art. 92, caput e § 1º.","","p16l",{}),
("P16",["92"],"E","troca_efeito",3,"A licença para o desempenho de mandato em confederação, federação, associação de classe de âmbito nacional ou sindicato representativo da categoria é concedida com remuneração e terá duração de dois anos, vedada a renovação em caso de reeleição.","Art. 92: sem remuneração; duração igual à do mandato, podendo ser renovada no caso de reeleição.","altera remuneração e duração","p16l",{}),
# P17
("P17",["93"],"C","conceito_correto",3,"O servidor poderá ser cedido para ter exercício em outro órgão ou entidade dos Poderes da União, dos Estados, do DF e dos Municípios para exercício de cargo em comissão ou função de confiança ou em casos previstos em leis específicas, mediante portaria publicada no Diário Oficial da União.","Art. 93, caput, I, II e § 3º.","","p17a",{}),
("P17",["93"],"E","troca_efeito",3,"Na cessão para exercício de cargo em comissão em órgão ou entidade de Estado, do Distrito Federal ou de Município, o ônus da remuneração será sempre do órgão ou entidade cedente, mantida a cessão por portaria publicada no Diário Oficial da União.","Art. 93, § 1º: nessa hipótese o ônus é do órgão ou entidade cessionária; mantém-se para o cedente nos demais casos.","inverte o ônus","p17a",{}),
("P17",["94"],"C","conceito_correto",2,"Ao servidor investido em mandato eletivo federal, estadual ou distrital aplica-se o afastamento do cargo; se prefeito, será afastado do cargo, sendo-lhe facultado optar pela sua remuneração.","Art. 94, I e II.","","p17b",{}),
("P17",["94"],"C","caso_concreto",3,"Servidor investido no mandato de vereador, havendo compatibilidade de horário, perceberá as vantagens de seu cargo, sem prejuízo da remuneração do cargo eletivo.","Art. 94, III, a.","","p17c",{}),
("P17",["94"],"E","caso_concreto",3,"Servidor investido no mandato de vereador será sempre afastado do cargo efetivo, sendo-lhe facultado optar pela remuneração, mesmo que haja compatibilidade de horário.","Art. 94, III: havendo compatibilidade, acumula as vantagens; só se não houver será afastado, com opção pela remuneração.","ignora compatibilidade","p17c",{}),
("P17",["94"],"C","conceito_correto",3,"O servidor investido em mandato eletivo ou classista não poderá ser removido ou redistribuído de ofício para localidade diversa daquela onde exerce o mandato.","Art. 94, § 2º.","","p17d",{}),
("P17",["95"],"C","troca_numero",3,"O servidor não poderá ausentar-se do País para estudo ou missão oficial sem autorização do Presidente da República, dos Presidentes dos órgãos do Poder Legislativo e do Presidente do STF, e a ausência não excederá quatro anos.","Art. 95, caput e § 1º.","","p17e",{}),
("P17",["95"],"E","troca_efeito",3,"Finda a missão ou estudo no exterior, que não poderá exceder quatro anos, o servidor poderá obter nova ausência imediatamente, e as regras do art. 95 aplicam-se também aos servidores da carreira diplomática.","Art. 95, §§ 1º e 3º: só decorrido igual período será permitida nova ausência; não se aplica aos servidores da carreira diplomática.","nega interstício e aplica à diplomática","p17e",{}),
("P17",["96"],"C","conceito_correto",3,"O afastamento de servidor para servir em organismo internacional de que o Brasil participe ou com o qual coopere dar-se-á com perda total da remuneração.","Art. 96.","","p17f",{}),
("P17",["96A"],"C","conceito_correto",3,"Os afastamentos para mestrado e doutorado somente serão concedidos a servidores titulares de cargos efetivos no órgão há pelo menos três anos para mestrado e quatro anos para doutorado, incluído o período de estágio probatório.","Art. 96-A, § 2º.","","p17g",{}),
("P17",["96A"],"E","troca_numero",3,"Os afastamentos para mestrado e doutorado somente serão concedidos a servidores titulares de cargos efetivos há pelo menos cinco anos para mestrado e seis anos para doutorado, excluído o período de estágio probatório.","Art. 96-A, § 2º: três anos (mestrado) e quatro anos (doutorado), incluído o estágio probatório.","altera prazos","p17g",{}),
("P17",["96A"],"C","consequencia",3,"O servidor beneficiado por afastamento para pós-graduação terá que permanecer no exercício de suas funções, após o retorno, por período igual ao do afastamento, sob pena de ressarcir os gastos com seu aperfeiçoamento caso peça exoneração ou aposentadoria antes.","Art. 96-A, §§ 4º e 5º.","","p17h",{}),
# P18
("P18",["97"],"C","conceito_correto",2,"Sem qualquer prejuízo, poderá o servidor ausentar-se do serviço por um dia para doação de sangue e por oito dias consecutivos em razão de casamento.","Art. 97, I e III, a.","","p18a",{}),
("P18",["97"],"E","troca_numero",2,"Sem qualquer prejuízo, poderá o servidor ausentar-se do serviço por três dias para doação de sangue e por cinco dias consecutivos em razão de casamento.","Art. 97: um dia para doação de sangue; oito dias consecutivos por casamento.","altera prazos","p18a",{}),
("P18",["97"],"C","troca_numero",3,"O servidor pode ausentar-se do serviço, sem prejuízo, pelo período comprovadamente necessário para alistamento ou recadastramento eleitoral, limitado, em qualquer caso, a dois dias.","Art. 97, II.","","p18b",{}),
("P18",["98"],"C","excecao_omitida",3,"Será concedido horário especial ao servidor estudante, quando comprovada a incompatibilidade entre o horário escolar e o da repartição, exigida a compensação de horário; ao servidor com deficiência, comprovada a necessidade por junta médica oficial, o horário especial independe de compensação.","Art. 98, caput, §§ 1º e 2º.","","p18c",{}),
("P18",["98"],"E","excecao_omitida",3,"O horário especial concedido ao servidor com deficiência, ao servidor estudante e ao que tenha cônjuge, filho ou dependente com deficiência exige sempre compensação de horário, comprovada a necessidade por junta médica oficial.","Art. 98, §§ 2º e 3º: para servidor com deficiência e quem tem dependente com deficiência, independe de compensação.","exige compensação indevida","p18c",{}),
("P18",["99"],"C","conceito_correto",3,"Ao servidor estudante que mudar de sede no interesse da administração é assegurada, na localidade da nova residência ou na mais próxima, matrícula em instituição de ensino congênere, em qualquer época, independentemente de vaga.","Art. 99.","","p18d",{}),
("P18",["100","103"],"C","conceito_correto",2,"É contado para todos os efeitos o tempo de serviço público federal, inclusive o prestado às Forças Armadas, ao passo que o tempo de serviço público prestado a Estados e Municípios conta apenas para fins de aposentadoria e disponibilidade.","Art. 100; art. 103, I.","","p18e",{}),
("P18",["100","103"],"E","generalizacao",2,"O tempo de serviço público prestado a Estados, Municípios e ao Distrito Federal é contado para todos os efeitos legais, inclusive para promoção e estágio probatório, assim como o tempo de serviço público federal.","Art. 103, I: conta-se apenas para efeito de aposentadoria e disponibilidade.","amplia contagem","p18e",{}),
("P18",["102"],"C","conceito_correto",3,"São considerados de efetivo exercício os afastamentos em virtude de férias, exercício de cargo em comissão, júri e outros serviços obrigatórios por lei, e licença à gestante, à adotante e à paternidade.","Art. 102, I, II, VI e VIII, a.","","p18f",{}),
("P18",["102"],"E","restricao_indevida",3,"A licença para tratar de interesses particulares e a licença por motivo de afastamento do cônjuge são consideradas de efetivo exercício para todos os efeitos, ao lado das férias e do júri.","Art. 102 não inclui as licenças dos arts. 81, II e VI, que não são de efetivo exercício.","inclui licenças não listadas","p18f",{}),
("P18",["103"],"C","conceito_correto",3,"É vedada a contagem cumulativa de tempo de serviço prestado concomitantemente em mais de um cargo ou função de órgãos ou entidades dos Poderes da União, Estados, DF e Municípios, autarquias, fundações públicas, sociedades de economia mista e empresas públicas.","Art. 103, § 3º.","","p18g",{}),
# P19
("P19",["104","105"],"C","conceito_correto",2,"O requerimento do servidor será dirigido à autoridade competente para decidi-lo e encaminhado por intermédio daquela a que estiver imediatamente subordinado o requerente.","Art. 105.","","p19a",{}),
("P19",["105"],"E","troca_autoridade",2,"O requerimento do servidor será dirigido à autoridade imediatamente superior ao requerente, que o encaminhará ao órgão de pessoal competente para decidi-lo.","Art. 105: dirigido à autoridade competente para decidir; encaminhado por intermédio da chefia imediata.","troca destinatário","p19a",{}),
("P19",["106"],"C","conceito_correto",2,"Cabe pedido de reconsideração à autoridade que houver expedido o ato ou proferido a primeira decisão, não podendo ser renovado, e deverá ser despachado em cinco dias e decidido em trinta dias.","Art. 106, caput e parágrafo único.","","p19b",{}),
("P19",["106"],"E","troca_numero",2,"Cabe pedido de reconsideração à autoridade que houver expedido o ato, podendo ser renovado uma vez, devendo ser despachado em cinco dias e decidido em sessenta dias.","Art. 106: não pode ser renovado; despacho em 5 dias e decisão em 30 dias.","permite renovação e altera prazo","p19b",{}),
("P19",["107","108"],"C","conceito_correto",3,"O recurso será dirigido à autoridade imediatamente superior à que tiver expedido o ato ou proferido a decisão, e o prazo para interposição de recurso ou pedido de reconsideração é de trinta dias, a contar da publicação ou da ciência da decisão recorrida.","Art. 107, § 1º; art. 108.","","p19c",{}),
("P19",["108"],"E","troca_numero",3,"O recurso será dirigido à autoridade que tiver expedido o ato ou proferido a decisão, e o prazo para interposição de pedido de reconsideração ou de recurso é de quinze dias, a contar da data do ato impugnado, ainda que o interessado dele não tenha ciência.","Art. 108: trinta dias, a contar da publicação ou da ciência pelo interessado.","altera prazo e termo","p19c",{}),
("P19",["109"],"C","conceito_correto",3,"O recurso poderá ser recebido com efeito suspensivo, a juízo da autoridade competente, e, provido o pedido de reconsideração ou o recurso, os efeitos da decisão retroagirão à data do ato impugnado.","Art. 109, caput e parágrafo único.","","p19d",{}),
("P19",["109"],"E","troca_efeito",3,"O recurso administrativo terá sempre efeito suspensivo, e, provido o pedido de reconsideração ou o recurso, o provimento produzirá efeitos somente a partir da data da decisão que o acolher.","Art. 109: efeito suspensivo a juízo da autoridade; provimento retroage à data do ato impugnado.","altera efeitos","p19d",{}),
("P19",["110"],"C","troca_numero",2,"O direito de requerer prescreve em cinco anos quanto aos atos de demissão e de cassação de aposentadoria ou disponibilidade, ou que afetem interesse patrimonial e créditos resultantes das relações de trabalho, e em cento e vinte dias nos demais casos.","Art. 110, I e II.","","p19e",{}),
("P19",["110"],"E","troca_numero",2,"O direito de requerer prescreve em cento e vinte dias quanto aos atos de demissão, de cassação de aposentadoria ou disponibilidade e aos que afetem interesse patrimonial, e em cinco anos nos demais casos.","Art. 110: cinco anos para demissão, cassação e interesse patrimonial; 120 dias nos demais casos.","inverte prazos","p19e",{}),
("P19",["111","112"],"C","conceito_correto",2,"O pedido de reconsideração e o recurso, quando cabíveis, interrompem a prescrição, e esta é de ordem pública, não podendo ser relevada pela administração.","Arts. 111 e 112.","","p19f",{}),
("P19",["111","112"],"E","troca_efeito",2,"A prescrição do direito de requerer é matéria de interesse do servidor e pode ser relevada pela administração, que, ademais, não é interrompida por pedido de reconsideração.","Arts. 111 e 112: a prescrição é de ordem pública e não pode ser relevada; o pedido e o recurso a interrompem.","altera natureza e efeito","p19f",{}),
("P19",["114"],"C","conceito_correto",2,"A administração deverá rever seus atos, a qualquer tempo, quando eivados de ilegalidade.","Art. 114.","","p19g",{}),
("P19",["115"],"C","excecao_omitida",3,"São fatais e improrrogáveis os prazos estabelecidos no capítulo do direito de petição, salvo motivo de força maior.","Art. 115.","","p19h",{}),
# P20
("P20",["116"],"C","conceito_correto",2,"É dever do servidor levar as irregularidades de que tiver ciência em razão do cargo ao conhecimento da autoridade superior ou, quando houver suspeita de envolvimento desta, ao conhecimento de outra autoridade competente para apuração.","Art. 116, VI.","","p20a",{}),
("P20",["116"],"E","restricao_indevida",2,"É dever do servidor levar as irregularidades de que tiver ciência em razão do cargo ao conhecimento exclusivamente da autoridade superior, ainda que haja suspeita de envolvimento desta na prática da irregularidade.","Art. 116, VI: havendo suspeita de envolvimento da autoridade superior, deve levar a outra autoridade competente.","omite a outra autoridade","p20a",{}),
("P20",["116"],"C","excecao_omitida",3,"É dever do servidor cumprir as ordens superiores, exceto quando manifestamente ilegais.","Art. 116, IV.","","p20b",{}),
("P20",["116"],"E","generalizacao",3,"É dever do servidor cumprir todas as ordens superiores, inclusive as manifestamente ilegais, respondendo pela ilegalidade apenas o superior que as emitiu.","Art. 116, IV: exceto as manifestamente ilegais.","omite a exceção","p20b",{}),
("P20",["116"],"C","conceito_correto",3,"A representação contra ilegalidade, omissão ou abuso de poder será encaminhada pela via hierárquica e apreciada pela autoridade superior àquela contra a qual é formulada, assegurando-se ao representando ampla defesa.","Art. 116, XII e parágrafo único.","","p20c",{}),
("P20",["116"],"E","troca_autoridade",3,"A representação contra ilegalidade, omissão ou abuso de poder será encaminhada pela via hierárquica e apreciada pela própria autoridade contra a qual é formulada, que decidirá sobre o seguimento, assegurando-se ao representando ampla defesa.","Art. 116, parágrafo único: apreciada pela autoridade superior àquela contra a qual é formulada.","troca autoridade","p20c",{}),
("P20",["117"],"C","conceito_correto",2,"É proibido ao servidor ausentar-se do serviço durante o expediente, sem prévia autorização do chefe imediato.","Art. 117, I.","","p20d",{}),
("P20",["117"],"E","troca_autoridade",2,"É proibido ao servidor ausentar-se do serviço durante o expediente, sem prévia autorização do dirigente máximo do órgão.","Art. 117, I: autorização do chefe imediato.","troca autoridade","p20d",{}),
("P20",["117"],"C","conceito_correto",3,"É proibido ao servidor manter sob sua chefia imediata, em cargo ou função de confiança, cônjuge, companheiro ou parente até o segundo grau civil.","Art. 117, VIII; SV 13.","","p20e",{}),
("P20",["117"],"E","troca_numero",3,"É proibido ao servidor manter sob sua chefia imediata, em cargo ou função de confiança, cônjuge, companheiro ou parente até o quarto grau civil.","Art. 117, VIII: até o segundo grau civil.","altera grau","p20e",{}),
("P20",["117"],"C","excecao_omitida",3,"É proibido ao servidor participar de gerência ou administração de sociedade privada, personificada ou não, ou exercer o comércio, exceto na qualidade de acionista, cotista ou comanditário.","Art. 117, X.","","p20f",{}),
("P20",["117"],"E","excecao_omitida",3,"É proibido ao servidor participar de qualquer sociedade privada, inclusive na qualidade de acionista, cotista ou comanditário, por configurar conflito de interesses.","Art. 117, X: a vedação não alcança a participação como acionista, cotista ou comanditário.","omite a exceção","p20f",{}),
("P20",["117"],"C","excecao_omitida",3,"É proibido ao servidor atuar como procurador ou intermediário junto a repartições públicas, salvo quando se tratar de benefícios previdenciários ou assistenciais de parentes até o segundo grau e de cônjuge ou companheiro.","Art. 117, XI.","","p20g",{}),
("P20",["117"],"E","troca_numero",3,"O servidor pode atuar como procurador ou intermediário junto a repartições públicas em benefício de qualquer parente até o quarto grau, bem como de cônjuge ou companheiro, em qualquer matéria, inclusive tributária.","Art. 117, XI: exceção restrita a benefícios previdenciários ou assistenciais de parentes até o segundo grau, cônjuge ou companheiro.","amplia exceção","p20g",{}),
("P20",["117"],"C","caso_concreto",2,"O servidor que receber de fornecedor um presente de valor considerável, em razão de suas atribuições, descumpre a proibição de receber propina, comissão, presente ou vantagem de qualquer espécie em razão das atribuições.","Art. 117, XII.","","p20h",{}),
("P20",["117"],"C","conceito_correto",3,"A vedação à participação em gerência ou administração de sociedade privada não se aplica ao servidor em gozo de licença para trato de interesses particulares, observada a legislação sobre conflito de interesses.","Art. 117, parágrafo único, II.","","p20i",{}),
# P21
("P21",["118"],"C","conceito_correto",2,"Ressalvados os casos previstos na Constituição, é vedada a acumulação remunerada de cargos públicos, e a proibição se estende a cargos, empregos e funções em autarquias, fundações públicas, empresas públicas e sociedades de economia mista.","Art. 118, caput e § 1º.","","p21a",{}),
("P21",["118"],"E","restricao_indevida",2,"Ressalvados os casos previstos na Constituição, é vedada a acumulação remunerada de cargos públicos, mas a proibição alcança somente a Administração direta, não se estendendo a autarquias, fundações públicas, empresas públicas e sociedades de economia mista.","Art. 118, § 1º: estende-se a autarquias, fundações públicas, empresas públicas e sociedades de economia mista.","restringe abrangência","p21a",{}),
("P21",["118"],"C","conceito_correto",3,"A acumulação de cargos, ainda que lícita, fica condicionada à comprovação da compatibilidade de horários, e considera-se acumulação proibida a percepção de vencimento de cargo efetivo com proventos da inatividade, salvo quando os cargos forem acumuláveis na atividade.","Art. 118, §§ 2º e 3º.","","p21b",{}),
("P21",["118"],"E","excecao_omitida",3,"A acumulação lícita de cargos dispensa a comprovação da compatibilidade de horários, bastando a previsão constitucional, e considera-se lícita a percepção de vencimento de cargo efetivo com proventos da inatividade em qualquer hipótese.","Art. 118, §§ 2º e 3º: a acumulação lícita fica condicionada à compatibilidade de horários; a percepção de vencimento com proventos é acumulação proibida, salvo quando os cargos forem acumuláveis na atividade.","dispensa compatibilidade","p21b",{}),
("P21",["119"],"C","conceito_correto",3,"O servidor não poderá exercer mais de um cargo em comissão, exceto no caso do parágrafo único do art. 9º, nem ser remunerado pela participação em órgão de deliberação coletiva.","Art. 119, caput.","","p21c",{}),
("P21",["119"],"E","excecao_omitida",3,"A vedação à remuneração pela participação em órgão de deliberação coletiva alcança, sem exceção, os conselhos de administração e fiscal de empresas públicas e sociedades de economia mista.","Art. 119, parágrafo único: não se aplica à remuneração pela participação em conselhos de administração e fiscal de empresas estatais, observada a legislação específica.","omite a exceção","p21c",{}),
("P21",["120"],"C","caso_concreto",3,"Servidor que acumula licitamente dois cargos efetivos e é investido em cargo em comissão ficará afastado de ambos, salvo se houver compatibilidade de horário e local com o exercício de um deles, declarada pelas autoridades máximas dos órgãos envolvidos.","Art. 120.","","p21d",{}),
("P21",["120"],"E","caso_concreto",3,"Servidor que acumula licitamente dois cargos efetivos e é investido em cargo em comissão continuará exercendo ambos os cargos efetivos, ficando afastado apenas do cargo em comissão, ainda que não haja compatibilidade de horário e local.","Art. 120: ficará afastado de ambos os cargos efetivos, salvo compatibilidade declarada pelas autoridades máximas.","inverte a regra","p21d",{}),
# P22
("P22",["121","125"],"C","conceito_correto",2,"O servidor responde civil, penal e administrativamente pelo exercício irregular de suas atribuições, e as sanções civis, penais e administrativas podem cumular-se, sendo independentes entre si.","Arts. 121 e 125.","","p22a",{}),
("P22",["125","126"],"E","troca_efeito",2,"A absolvição criminal, por qualquer fundamento, afasta a responsabilidade administrativa do servidor, em razão da dependência entre as instâncias.","Arts. 125 e 126: as instâncias são independentes; só a absolvição que negue a existência do fato ou sua autoria afasta a responsabilidade administrativa.","afirma dependência total","p22b",{}),
("P22",["126"],"C","excecao_omitida",3,"A responsabilidade administrativa do servidor será afastada no caso de absolvição criminal que negue a existência do fato ou sua autoria.","Art. 126.","","p22b",{}),
("P22",["122"],"C","conceito_correto",3,"Tratando-se de dano causado a terceiros, responderá o servidor perante a Fazenda Pública, em ação regressiva, e a obrigação de reparar o dano estende-se aos sucessores, até o limite do valor da herança recebida.","Art. 122, §§ 2º e 3º.","","p22c",{}),
("P22",["122"],"E","troca_efeito",3,"Tratando-se de dano causado a terceiros, o servidor responderá diretamente perante o lesado, em ação de reparação, e a obrigação de reparar o dano não se estende aos sucessores, ainda que haja herança.","Art. 122, §§ 2º e 3º: responde perante a Fazenda Pública em ação regressiva; a obrigação estende-se aos sucessores até o limite da herança.","nega regressiva e sucessão","p22c",{}),
("P22",["126A"],"C","conceito_correto",3,"Nenhum servidor poderá ser responsabilizado civil, penal ou administrativamente por dar ciência à autoridade superior, ou a outra autoridade competente quando houver suspeita de envolvimento daquela, de informação sobre crimes ou improbidade de que tenha conhecimento.","Art. 126-A.","","p22d",{}),
# P23
("P23",["127"],"C","conceito_correto",1,"São penalidades disciplinares a advertência, a suspensão, a demissão, a cassação de aposentadoria ou disponibilidade, a destituição de cargo em comissão e a destituição de função comissionada.","Art. 127.","","p23a",{}),
("P23",["127"],"E","confusao_instituto",1,"São penalidades disciplinares a advertência, a suspensão, a demissão, a exoneração, a multa e a destituição de função comissionada.","Art. 127: exoneração e multa não integram o rol de penalidades disciplinares (a multa é conversão da suspensão, art. 130, § 2º).","inclui o que não é penalidade","p23a",{}),
("P23",["128"],"C","conceito_correto",2,"Na aplicação das penalidades serão consideradas a natureza e a gravidade da infração, os danos para o serviço público, as circunstâncias agravantes ou atenuantes e os antecedentes funcionais; o ato mencionará sempre o fundamento legal e a causa da sanção.","Art. 128.","","p23b",{}),
("P23",["129"],"C","conceito_correto",3,"A advertência será aplicada por escrito, nos casos de violação de proibição constante do art. 117, incisos I a VIII e XIX, e de inobservância de dever funcional que não justifique penalidade mais grave.","Art. 129.","","p23c",{}),
("P23",["129"],"E","troca_efeito",3,"A advertência será aplicada verbalmente ou por escrito, nos casos de violação das proibições do art. 117, incisos I a XVIII, e de inobservância de dever funcional que não justifique penalidade mais grave.","Art. 129: por escrito; proibições do art. 117, I a VIII e XIX.","altera forma e incisos","p23c",{}),
("P23",["130"],"C","troca_numero",2,"A suspensão será aplicada em caso de reincidência das faltas punidas com advertência e de violação das demais proibições que não tipifiquem infração sujeita a demissão, não podendo exceder noventa dias.","Art. 130, caput.","","p23d",{}),
("P23",["130"],"E","troca_numero",2,"A suspensão será aplicada em caso de reincidência das faltas punidas com advertência e de violação das proibições que não tipifiquem demissão, não podendo exceder cento e oitenta dias.","Art. 130: não pode exceder 90 dias.","altera limite","p23d",{}),
("P23",["130"],"C","conceito_correto",3,"Quando houver conveniência para o serviço, a penalidade de suspensão poderá ser convertida em multa, na base de 50% por dia de vencimento ou remuneração, ficando o servidor obrigado a permanecer em serviço.","Art. 130, § 2º.","","p23e",{}),
("P23",["130"],"E","troca_efeito",3,"Quando houver conveniência para o serviço, a penalidade de suspensão poderá ser convertida em multa, na base de 100% por dia de vencimento, ficando o servidor afastado do serviço até o pagamento.","Art. 130, § 2º: 50% por dia; o servidor permanece em serviço.","altera percentual e efeito","p23e",{}),
("P23",["130"],"C","troca_numero",3,"Será punido com suspensão de até quinze dias o servidor que, injustificadamente, recusar-se a ser submetido a inspeção médica determinada pela autoridade competente, cessando os efeitos da penalidade uma vez cumprida a determinação.","Art. 130, § 1º.","","p23f",{}),
("P23",["131"],"C","troca_numero",3,"As penalidades de advertência e de suspensão terão seus registros cancelados após o decurso de três e cinco anos de efetivo exercício, respectivamente, se o servidor não houver praticado nova infração disciplinar, sem efeitos retroativos.","Art. 131, caput e parágrafo único.","","p23g",{}),
("P23",["131"],"E","troca_numero",3,"As penalidades de advertência e de suspensão terão seus registros cancelados após o decurso de cinco e três anos de efetivo exercício, respectivamente, se o servidor não houver praticado nova infração, com efeitos retroativos.","Art. 131: advertência em 3 anos, suspensão em 5; cancelamento não surte efeitos retroativos.","inverte prazos e efeito","p23g",{}),
("P23",["132"],"C","conceito_correto",2,"A demissão será aplicada, entre outros casos, em crime contra a administração pública, abandono de cargo, inassiduidade habitual, improbidade administrativa, corrupção e acumulação ilegal de cargos, empregos ou funções públicas.","Art. 132, I, II, III, IV, XI e XII.","","p23h",{}),
("P23",["132"],"E","confusao_instituto",2,"A demissão será aplicada, entre outros casos, em ausência injustificada de um dia ao serviço, em recusa a atualizar dados cadastrais e em descumprimento de horário de trabalho, ainda que sem reincidência.","Art. 132 não prevê tais hipóteses; a recusa de atualização cadastral (art. 117, XIX) é punida, em regra, com advertência (art. 129).","inclui hipóteses inexistentes","p23h",{}),
("P23",["132","117"],"C","conceito_correto",3,"A transgressão dos incisos IX a XVI do art. 117 é causa de demissão, nos termos do art. 132, XIII, entre elas valer-se do cargo para lograr proveito pessoal, receber propina e utilizar recursos da repartição em atividades particulares.","Art. 132, XIII; art. 117, IX, XII e XVI.","","p23i",{}),
("P23",["134"],"C","conceito_correto",2,"Será cassada a aposentadoria ou a disponibilidade do inativo que houver praticado, na atividade, falta punível com a demissão.","Art. 134.","","p23j",{}),
("P23",["135"],"C","conceito_correto",3,"A destituição de cargo em comissão exercido por não ocupante de cargo efetivo será aplicada nos casos de infração sujeita às penalidades de suspensão e de demissão, e a exoneração efetuada nos termos do art. 35 será convertida em destituição.","Art. 135, caput e parágrafo único.","","p23k",{}),
("P23",["136"],"C","conceito_correto",3,"A demissão ou destituição de cargo em comissão nos casos de improbidade administrativa, aplicação irregular de dinheiros públicos, lesão aos cofres públicos e corrupção implica indisponibilidade dos bens e ressarcimento ao erário, sem prejuízo da ação penal.","Art. 136; art. 132, IV, VIII, X e XI.","","p23l",{}),
("P23",["137"],"C","troca_numero",3,"A demissão ou destituição por valer-se do cargo para proveito pessoal ou por atuar como procurador junto a repartições públicas incompatibiliza o ex-servidor para nova investidura em cargo público federal pelo prazo de cinco anos.","Art. 137, caput.","","p23m",{}),
("P23",["137"],"E","troca_efeito",3,"O servidor demitido por improbidade administrativa, lesão aos cofres públicos ou corrupção fica incompatibilizado para nova investidura em cargo público federal pelo prazo de cinco anos, podendo retornar depois.","Art. 137, parágrafo único: nesses casos (art. 132, I, IV, VIII, X e XI) não poderá retornar ao serviço público federal.","troca vedação permanente por temporária","p23m",{}),
("P23",["141"],"C","troca_autoridade",3,"A demissão e a cassação de aposentadoria ou disponibilidade de servidor vinculado ao respectivo Poder serão aplicadas pelo Presidente da República, pelos Presidentes das Casas do Poder Legislativo e dos Tribunais Federais e pelo Procurador-Geral da República.","Art. 141, I.","","p23n",{}),
("P23",["141"],"E","troca_autoridade",3,"A advertência e a suspensão de até trinta dias serão aplicadas exclusivamente pelo Presidente da República, ou pelos Presidentes das Casas Legislativas e dos Tribunais Federais, e pelo Procurador-Geral da República.","Art. 141, III: chefe da repartição e outras autoridades, na forma dos regimentos ou regulamentos.","concentra competência","p23n",{}),
("P23",["141"],"C","troca_autoridade",3,"A suspensão superior a trinta dias é aplicada pelas autoridades administrativas de hierarquia imediatamente inferior às que aplicam a demissão, e a destituição de cargo em comissão, pela autoridade que houver feito a nomeação.","Art. 141, II e IV.","","p23o",{}),
# P24
("P24",["138"],"C","conceito_correto",1,"Configura abandono de cargo a ausência intencional do servidor ao serviço por mais de trinta dias consecutivos.","Art. 138.","","p24a",{}),
("P24",["138"],"E","troca_numero",1,"Configura abandono de cargo a ausência intencional do servidor ao serviço por mais de sessenta dias consecutivos.","Art. 138: mais de trinta dias consecutivos (60 dias é o parâmetro da inassiduidade).","troca prazos","p24a",{}),
("P24",["139"],"C","conceito_correto",2,"Entende-se por inassiduidade habitual a falta ao serviço, sem causa justificada, por sessenta dias, interpoladamente, durante o período de doze meses.","Art. 139.","","p24b",{}),
("P24",["139"],"E","troca_efeito",2,"Entende-se por inassiduidade habitual a falta ao serviço, sem causa justificada, por mais de trinta dias consecutivos, durante o período de doze meses.","Art. 139: sessenta dias interpoladamente em doze meses (o conceito dado é o de abandono).","troca instituto","p24b",{}),
("P24",["142"],"C","troca_numero",2,"A ação disciplinar prescreverá em cinco anos quanto às infrações puníveis com demissão, cassação de aposentadoria ou disponibilidade e destituição de cargo em comissão, em dois anos quanto à suspensão e em cento e oitenta dias quanto à advertência.","Art. 142, I, II e III.","","p24c",{}),
("P24",["142"],"E","troca_numero",2,"A ação disciplinar prescreverá em dois anos quanto às infrações puníveis com demissão, cassação de aposentadoria ou disponibilidade e destituição, em cinco anos quanto à suspensão e em noventa dias quanto à advertência.","Art. 142: 5 anos (demissão), 2 anos (suspensão), 180 dias (advertência).","embaralha prazos","p24c",{}),
("P24",["142"],"C","caso_concreto",3,"Servidor praticou infração que também é capitulada como crime com pena cuja prescrição penal é de doze anos; nesse caso, aplica-se à infração disciplinar o prazo prescricional previsto na lei penal.","Art. 142, § 2º.","","p24d",{}),
("P24",["142"],"E","caso_concreto",3,"Servidor praticou infração que também é capitulada como crime com pena cuja prescrição penal é de doze anos; ainda assim, a infração disciplinar prescreve nos prazos do art. 142, I a III, da Lei n.º 8.112/1990.","Art. 142, § 2º: os prazos da lei penal aplicam-se às infrações também capituladas como crime.","ignora prazo penal","p24d",{}),
("P24",["142"],"C","conceito_correto",3,"O prazo de prescrição da ação disciplinar começa a correr da data em que o fato se tornou conhecido, e a abertura de sindicância ou a instauração de processo disciplinar interrompe a prescrição até a decisão final proferida por autoridade competente.","Art. 142, §§ 1º e 3º.","","p24e",{}),
("P24",["142"],"E","troca_efeito",3,"O prazo de prescrição da ação disciplinar começa a correr da data em que a infração foi praticada, e a abertura de sindicância ou a instauração de processo disciplinar apenas suspende a prescrição por sessenta dias.","Art. 142, §§ 1º e 3º: conta-se da data em que o fato se tornou conhecido; a abertura de sindicância ou PAD interrompe até a decisão final.","altera termo e efeito","p24e",{}),
]
